mapper.select:
SELECT user_id, username, open_id, real_name, student_name, relationship, phone, avatar_url, role_type, dance_class_name, enrollment_year, remaining_hours, volunteer_points, status, created_at
FROM sys_user
WHERE user_id = #{userId}

SELECT user_id, username, open_id, real_name, student_name, relationship, phone, avatar_url, role_type, dance_class_name, enrollment_year, remaining_hours, volunteer_points, status, created_at FROM sys_user WHERE status = 0
AND dance_class_name = #{danceClassName}
ORDER BY user_id DESC

mapper.update:
UPDATE sys_user
SET status = #{status}
WHERE user_id = #{userId}

UPDATE sys_user
SET volunteer_points = volunteer_points + #{points}
WHERE user_id = #{userId}

mapper.insert:
INSERT INTO sys_user (
    user_id, username, open_id, real_name, student_name, relationship, phone, avatar_url, role_type, dance_class_name, enrollment_year, remaining_hours, volunteer_points, status
) VALUES (
    #{userId}, #{username}, #{openId}, #{realName}, #{studentName}, #{relationship}, #{phone}, #{avatarUrl}, #{roleType}, #{danceClassName}, #{enrollmentYear}, #{remainingHours}, #{volunteerPoints}, #{status}
)
